import XCTest

class ElementUITests: XCTestCase {

    func testTapBobConversation() {
        let app = XCUIApplication()
        app.launch()

        // Wait a moment
        sleep(1)

        // Try to dismiss any alerts by clicking the first button (Usually Cancel)
        if app.alerts.count > 0 {
            let alert = app.alerts.firstMatch
            let cancelButton = alert.buttons.element(boundBy: 0)
            if cancelButton.exists {
                cancelButton.tap()
            }
        }

        sleep(1)

        // Tap on Bob's conversation
        let bobElement = app.cells.containing(.staticText, identifier: "Bob").firstMatch
        if bobElement.exists {
            bobElement.tap()
        }
    }
}
EOF

